"""Shared Alembic settings and metadata."""

from sqlalchemy.engine import URL

from app.core.config import get_settings
from app.models import Base

# Alembic uses the same metadata that future ORM models inherit from.
target_metadata = Base.metadata


def get_migration_url() -> URL:
    """Return the validated database URL used by the FastAPI application."""

    return get_settings().sqlalchemy_url


def include_object(object_, name, type_, reflected, compare_to):
    """Avoid treating unmodeled existing tables as autogenerated drops."""

    if type_ == "table" and reflected and compare_to is None:
        return False
    return True
